const { deliver } = require('/workspace/src/dispatcher.js');

function makeIo(statuses, throwsAt) {
  const calls = [];
  const sleeps = [];
  const io = {
    post: async (path, body, opts) => {
      calls.push({ path, body, opts });
      if (throwsAt && calls.length === throwsAt) throw new Error('ECONNRESET');
      return statuses.length === 0 ? { status: 200 } : { status: statuses.shift() };
    },
    sleep: async (ms) => { sleeps.push(ms); },
  };
  return { io, calls, sleeps };
}

(async () => {
  // 1. Success on first attempt
  const t1 = makeIo([200]);
  const r1 = await deliver(t1.io, { id: 'evt_1' });
  console.log('1) first try 200 ->', JSON.stringify(r1), 'posts:', t1.calls.length, 'sleeps:', t1.sleeps);

  // 2. 502 then success: retries with backoff and idempotency key on every attempt
  const t2 = makeIo([502, 200]);
  const r2 = await deliver(t2.io, { id: 'evt_2' });
  console.log('2) 502 then 200 ->', JSON.stringify(r2), 'posts:', t2.calls.length, 'sleeps:', t2.sleeps);
  console.log('   headers:', t2.calls.map(c => c.opts && c.opts.headers));

  // 3. Persistent 502: 5 attempts, backoff 100,200,400,800,1600, returns {status:502}
  const t3 = makeIo([502, 502, 502, 502, 502]);
  const r3 = await deliver(t3.io, { id: 'evt_3' });
  console.log('3) always 502 ->', JSON.stringify(r3), 'posts:', t3.calls.length, 'sleeps:', t3.sleeps);

  // 4. 4xx is not retried
  const t4 = makeIo([400]);
  const r4 = await deliver(t4.io, { id: 'evt_4' });
  console.log('4) 400 ->', JSON.stringify(r4), 'posts:', t4.calls.length, 'sleeps:', t4.sleeps);

  // 5. Network error then success
  const t5 = makeIo([200], 1);
  const r5 = await deliver(t5.io, { id: 'evt_5' });
  console.log('5) throw then 200 ->', JSON.stringify(r5), 'posts:', t5.calls.length, 'sleeps:', t5.sleeps);
})();
"

